      expect(() => editor.onScaleChanging()).not.toThrow();
    });

    it("should call super and update SVG properties when parent exists", () => {
      const mockParent = createMockParent();
      const mockDrawingOptions = {
        updateSVGProperty: jest.fn(),
        toSVGProperties: jest.fn().mockReturnValue({ "stroke-width": 2 }),
      };

      const editor = new InkEditor({
        uiManager: { viewParameters: { rotation: 0 } },
        parent: mockParent
      });
      editor._drawId = "testDrawId";
