import { InkEditor } from "../../../../src/display/editor/ink.js";

describe("InkEditor", () => {
  let editor;
  let mockAnnotation;

  beforeEach(() => {
    const mockParent = {
      pageIndex: 0,
      viewport: {
        rotation: 0,
        rawDims: {
          pageWidth: 800,
          pageHeight: 600,
          pageX: 0,
          pageY: 0,
        },
      },
    };

    const mockUiManager = {
      isWaiting: false,
      viewParameters: {
        rotation: 0,
      },
    };

    editor = new InkEditor({
      parent: mockParent,
      uiManager: mockUiManager,
    });

    editor.deleted = false;
    editor.comment = "Test comment";
    editor._drawingOptions = {
      "stroke-width": 2,
    };

    editor.serializeDraw = jest.fn(() => ({
      points: [[0, 0], [10, 10]],
      rect: [0, 0, 100, 100],
    }));

    mockAnnotation = {
      hide: jest.fn(),
      updateEdited: jest.fn(),
    };
  });

  describe("renderAnnotationElement", () => {
    it("should hide the annotation and return null if the editor is deleted", () => {
      editor.deleted = true;

      const result = editor.renderAnnotationElement(mockAnnotation);

      expect(mockAnnotation.hide).toHaveBeenCalled();
      expect(result).toBeNull();
      expect(mockAnnotation.updateEdited).not.toHaveBeenCalled();
    });

    it("should update the annotation with serialized data and return null when not deleted", () => {
      const result = editor.renderAnnotationElement(mockAnnotation);

      expect(mockAnnotation.hide).not.toHaveBeenCalled();

      expect(editor.serializeDraw).toHaveBeenCalledWith(false);

      expect(mockAnnotation.updateEdited).toHaveBeenCalledWith({
        rect: [0, 0, 100, 100],
        thickness: 2,
        points: [[0, 0], [10, 10]],
        popup: "Test comment",
      });

      expect(result).toBeNull();
    });
  });
});

