jest.mock('../../../src/scripting_api/color', () => {
  const OriginalModule = jest.requireActual('../../../src/scripting_api/color');

  // We need to make sure the mock preserves the structure
  return {
    ...OriginalModule,
    Color: class extends OriginalModule.Color {
      constructor() {
        super();
      }
    }
  };
});

// We mock ColorConverters by spying on the functions, as mocking the whole module 
// inside the file where Color is defined is complex due to circular dependencies or structure.
// Instead, we spyOn the actual conversion functions if they exist, or mock the object.

describe('Color.convert', () => {
  let colorInstance;

  beforeAll(() => {
    // Define mocks for the specific converters we need to test
    ColorConverters.G_RGB = jest.fn((val) => ['RGB', val, val, val]);
    ColorConverters.RGB_CMYK = jest.fn((r, g, b) => ['CMYK', 1 - r, 1 - g, 1 - b, 0]);
    ColorConverters.CMYK_RGB = jest.fn((c, m, y, k) => ['RGB', 1 - c, 1 - m, 1 - y]);
  });

  beforeEach(() => {
    colorInstance = new Color();
    jest.clearAllMocks();
  });

  it('should return black if target color space is invalid', () => {
    const result = colorInstance.convert(['RGB', 1, 0, 0], 'INVALID_SPACE');
    expect(result).toEqual(colorInstance.black);
  });

  it('should return ["T"] if target color space is "T"', () => {
    const result = colorInstance.convert(['RGB', 1, 0, 0], 'T');
    expect(result).toEqual(['T']);
  });

  it('should return the original array if the source and target spaces are the same', () => {
    const inputArray = ['RGB', 0.5, 0.5, 0.5];
    const result = colorInstance.convert(inputArray, 'RGB');
    expect(result).toBe(inputArray);
  });

  it('should return black converted to target space if source space is "T"', () => {
    const targetSpace = 'RGB';
    const result = colorInstance.convert(['T'], targetSpace);

    // Source is T. Logic calls convert(this.black, targetSpace).
    // this.black is ["G", 0]. 
    // It looks for ColorConverters['G_RGB'](0)
    expect(ColorConverters.G_RGB).toHaveBeenCalledWith(0);
    expect(result).toEqual(['RGB', 0, 0, 0]);
  });

  it('should call the specific converter if spaces differ and neither is T', () => {
    const inputArray = ['G', 0.5];
    const targetSpace = 'RGB';
    const result = colorInstance.convert(inputArray, targetSpace);

    expect(ColorConverters.G_RGB).toHaveBeenCalledWith(0.5);
    expect(result).toEqual(['RGB', 0.5, 0.5, 0.5]);
  });

  it('should handle RGB to CMYK conversion', () => {
    const inputArray = ['RGB', 1, 0, 0];
    const targetSpace = 'CMYK';
    const result = colorInstance.convert(inputArray, targetSpace);

    expect(ColorConverters.RGB_CMYK).toHaveBeenCalledWith(1, 0, 0);
    expect(result).toEqual(['CMYK', 0, 1, 1, 0]);
  });

  it('should handle CMYK to RGB conversion', () => {
    const inputArray = ['CMYK', 1, 0, 0, 0];
    const targetSpace = 'RGB';
    const result = colorInstance.convert(inputArray, targetSpace);

    expect(ColorConverters.CMYK_RGB).toHaveBeenCalledWith(1, 0, 0, 0);
    expect(result).toEqual(['RGB', 0, 1, 1]);
  });
});

