    const hash1 = { h1: hasher.h1, h2: hasher.h2 };

    hasher = new MurmurHash3_64(0);
    hasher.update('a\u0100c');
    const hash2 = { h1: hasher.h1, h2: hasher.h2 };

    expect(hash1).not.toEqual(hash2);
  });

  it('should process TypedArray (Uint8Array)', () => {
