    doc._send = mockSend;
    doc._userActivation = true;
    doc._disablePrinting = false;
  });

  describe('print', () => {
    it('should send print command with default parameters', () => {
      doc.print();

      expect(mockSend).toHaveBeenCalledWith({
        command: 'print',
        start: 0,
        end: 0,
      });
    });

    it('should normalize start and end page numbers', () => {
      doc.print(5.9, 10.9);

      expect(mockSend).toHaveBeenCalledWith({
        command: 'print',
        start: 10,
        end: 0,
      });
    });

    it('should clamp start page to 0 if negative', () => {
      doc.print(-5, 10);

      expect(mockSend).toHaveBeenCalledWith({
        command: 'print',
        start: 10,
        end: 0,
      });
    });

    it('should clamp end page to 0 if negative', () => {
      doc.print(0, -10);

      expect(mockSend).toHaveBeenCalledWith({
        command: 'print',
        start: 0,
        end: 0,
      });
    });

    it('should handle NaN start and end pages by defaulting to 0 and 0', () => {
      doc.print('abc', 'def');

      expect(mockSend).toHaveBeenCalledWith({
        command: 'print',
        start: 0,
        end: 0,
      });
    });

