        bUI: false,
        nStart: 2,
        nEnd: 4,
        bSilent: true,
        bShrinkToFit: true,
        bPrintAsImage: true,
        bReverse: true,
        bAnnotations: false,
        printParams: null,
      });

      expect(mockSend).toHaveBeenCalledWith({
        command: 'print',
        start: 2,
        end: 4,
      });
    });

    it('should override nStart/nEnd if printParams is provided', () => {
      doc.print(0, 10, false, false, false, false, false, true, {
        firstPage: 5,
        lastPage: 7,
      });

      expect(mockSend).toHaveBeenCalledWith({
        command: 'print',
        start: 5,
        end: 7,
      });
    });

