import { convertRGBToRGBA } from '../../../src/shared/image_utils.js';

describe('convertRGBToRGBA', () => {
  const createRGBBuffer = (pixels) => {
    const buffer = new Uint8Array(pixels.length * 3);
    for (let i = 0; i < pixels.length; i++) {
      buffer[i * 3] = pixels[i].r;
      buffer[i * 3 + 1] = pixels[i].g;
      buffer[i * 3 + 2] = pixels[i].b;
    }
    return buffer;
  };

  const createEmptyRGBABuffer = (size) => {
    return new Uint32Array(size);
  };

  const pixelsToRGBA = (r, g, b, isLittleEndian) => {
    if (isLittleEndian) {
      return 0xff000000 | (b << 16) | (g << 8) | r;
    } else {
      return 0xff | (r << 24) | (g << 16) | (b << 8);
    }
  };

  const isLittleEndian = new Uint8Array(new Uint32Array([0x12345678]).buffer)[0] === 0x78;

  it('should convert 1x1 RGB to RGBA', () => {
    const width = 1;
    const height = 1;
    const src = createRGBBuffer([{ r: 255, g: 0, b: 0 }]);
    const dest = createEmptyRGBABuffer(1);

    const result = convertRGBToRGBA({ src, dest, width, height });

    expect(result.destPos).toBe(4);
    expect(result.srcPos).toBe(3);

    const expected = pixelsToRGBA(255, 0, 0, isLittleEndian);
    expect(dest[0]).toBe(expected);
  });

  it('should convert a 2x2 image (partial 32-bit batch + remainder)', () => {
    const width = 2;
    const height = 2;
    const rgbPixels = [
      { r: 10, g: 20, b: 30 },
      { r: 40, g: 50, b: 60 },
      { r: 70, g: 80, b: 90 },
      { r: 100, g: 110, b: 120 },
    ];
    const src = createRGBBuffer(rgbPixels);
    const dest = createEmptyRGBABuffer(4);

    const result = convertRGBToRGBA({ src, dest, width, height });

    expect(result.destPos).toBe(16);
    expect(result.srcPos).toBe(12);

    for (let i = 0; i < 4; i++) {
      const p = rgbPixels[i];
      const expected = pixelsToRGBA(p.r, p.g, p.b, isLittleEndian);
      expect(dest[i]).toBe(expected);
    }
  });

  it('should convert an image requiring multiple full 32-bit loops (3x3)', () => {
    const width = 3;
    const height = 3;
    const rgbPixels = Array.from({ length: 9 }, (_, i) => ({
      r: i * 10 + 1,
      g: i * 10 + 2,
      b: i * 10 + 3,
    }));
    const src = createRGBBuffer(rgbPixels);
    const dest = createEmptyRGBABuffer(9);

    const result = convertRGBToRGBA({ src, dest, width, height });

    expect(result.destPos).toBe(36);
    expect(result.srcPos).toBe(27);

    for (let i = 0; i < 9; i++) {
      const p = rgbPixels[i];
      const expected = pixelsToRGBA(p.r, p.g, p.b, isLittleEndian);
      expect(dest[i]).toBe(expected);
    }
  });

  it('should handle custom srcPos and destPos offsets', () => {
    const width = 1;
    const height = 1;
    const src = createRGBBuffer([{ r: 1, g: 2, b: 3 }, { r: 4, g: 5, b: 6 }]);
    const dest = createEmptyRGBABuffer(3);

    const result = convertRGBToRGBA({
      src,
      srcPos: 3,
      dest,
      destPos: 1,
      width,
      height,
    });

    expect(result.srcPos).toBe(6);
    expect(result.destPos).toBe(5);

    // First pixel in dest should remain 0
    expect(dest[0]).toBe(0);

    // Second pixel should be converted from second RGB pixel
    const expected = pixelsToRGBA(4, 5, 6, isLittleEndian);
    expect(dest[1]).toBe(expected);

    // Third pixel should remain 0
    expect(dest[2]).toBe(0);
  });

  it('should handle full alpha channel setting (0xFF) for all pixels', () => {
    const width = 2;
    const height = 2;
    const src = createRGBBuffer([
      { r: 0, g: 0, b: 0 },
      { r: 255, g: 255, b: 255 },
      { r: 128, g: 128, b: 128 },
      { r: 1, g: 1, b: 1 },
    ]);
    const dest = createEmptyRGBABuffer(4);

    convertRGBToRGBA({ src, dest, width, height });

    dest.forEach((val) => {
      if (isLittleEndian) {
        expect(val & 0xff000000).toBe(0xff000000);
      } else {
        expect(val & 0x000000ff).toBe(0x000000ff);
      }
    });
  });
});

