const { PDFPageView } = require("../../web/pdf_page_view.js");

describe("PDFPageView", () => {
  let container;
  let pdfPageMock;

  beforeEach(() => {
    container = document.createElement("div");
    document.body.append(container);

    pdfPageMock = {
      _pdfBug: false,
      get viewport() {
        return { rotation: 0, width: 100, height: 100 };
      },
      getAnnotations() {
        return Promise.resolve([]);
      },
      cleanup() {},
    };

    // Mock AppOptions dependencies
    jest.spyOn(AppOptions, "get").mockImplementation((key) => {
      switch (key) {
        case "maxCanvasPixels":
          return 100000;
        case "maxCanvasDim":
          return 10000;
        case "capCanvasAreaFactor":
          return 1;
        default:
          return null;
      }
    });
  });

  afterEach(() => {
    container.remove();
    jest.restoreAllMocks();
  });

  describe("reset", () => {
    it("resets the view by cancelling rendering and removing all layers", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      // Mock internal methods/classes to simulate state
      pdfPageView._annotationCanvasMap = new Map();
      pdfPageView.annotationLayer = { hide: jest.fn(), div: document.createElement("div") };
      pdfPageView.annotationEditorLayer = { hide: jest.fn(), div: document.createElement("div") };
      pdfPageView.textLayer = { hide: jest.fn(), div: document.createElement("div") };
      pdfPageView.xfaLayer = { hide: jest.fn(), div: document.createElement("div") };
      pdfPageView.structTreeLayer = { hide: jest.fn() };

      // Simulate rendering state
      pdfPageView.renderingState = RenderingStates.RUNNING;
      pdfPageView.div.setAttribute("data-loaded", "true");

      // Call reset
      pdfPageView.reset();

      // Verify rendering state reset
      expect(pdfPageView.renderingState).toBe(RenderingStates.INITIAL);

      // Verify attribute removal
      expect(pdfPageView.div.hasAttribute("data-loaded")).toBe(false);

      // Verify layers were hidden
      expect(pdfPageView.annotationLayer.hide).toHaveBeenCalled();
      expect(pdfPageView.annotationEditorLayer.hide).toHaveBeenCalled();
      expect(pdfPageView.textLayer.hide).toHaveBeenCalled();
      expect(pdfPageView.xfaLayer.hide).toHaveBeenCalled();
      expect(pdfPageView.structTreeLayer.hide).toHaveBeenCalled();

      // Verify canvas and detail view reset
      expect(pdfPageView.detailView).toBeNull();
    });

    it("keeps the annotation layer when keepAnnotationLayer is true", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      const annotationDiv = document.createElement("div");
      annotationDiv.className = "annotationLayer";
      pdfPageView.div.append(annotationDiv);
      pdfPageView.annotationLayer = { hide: jest.fn(), div: annotationDiv };

      // Add another element to ensure it gets removed
      const extraDiv = document.createElement("div");
      pdfPageView.div.append(extraDiv);

      expect(pdfPageView.div.contains(annotationDiv)).toBe(true);
      expect(pdfPageView.div.contains(extraDiv)).toBe(true);

      pdfPageView.reset({ keepAnnotationLayer: true });

      expect(pdfPageView.div.contains(annotationDiv)).toBe(true);
      expect(pdfPageView.div.contains(extraDiv)).toBe(false);
      expect(pdfPageView.annotationLayer.hide).toHaveBeenCalled();
    });

    it("keeps the text layer when keepTextLayer is true", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      const textDiv = document.createElement("div");
      textDiv.className = "textLayer";
      pdfPageView.div.append(textDiv);
      pdfPageView.textLayer = { hide: jest.fn(), div: textDiv };

      const extraDiv = document.createElement("div");
      pdfPageView.div.append(extraDiv);

      pdfPageView.reset({ keepTextLayer: true });

      expect(pdfPageView.div.contains(textDiv)).toBe(true);
      expect(pdfPageView.div.contains(extraDiv)).toBe(false);
      expect(pdfPageView.textLayer.hide).toHaveBeenCalled();
    });

    it("keeps the XFA layer when keepXfaLayer is true", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      const xfaDiv = document.createElement("div");
      xfaDiv.className = "xfaLayer";
      pdfPageView.div.append(xfaDiv);
      pdfPageView.xfaLayer = { hide: jest.fn(), div: xfaDiv };

      pdfPageView.reset({ keepXfaLayer: true });

      expect(pdfPageView.div.contains(xfaDiv)).toBe(true);
      expect(pdfPageView.xfaLayer.hide).toHaveBeenCalled();
    });

    it("keeps the canvas wrapper when keepCanvasWrapper is true", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      const extraDiv = document.createElement("div");
      pdfPageView.div.append(extraDiv);

      expect(() => pdfPageView.reset({ keepCanvasWrapper: true })).not.toThrow();
      expect(pdfPageView.div.contains(extraDiv)).toBe(false);
    });

    it("resets the canvas wrapper when keepCanvasWrapper is false", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      pdfPageView._resetCanvas = jest.fn();

      pdfPageView.reset({ keepCanvasWrapper: false });

      // _resetCanvas is not called because #canvasWrapper is null
      expect(pdfPageView._resetCanvas).not.toHaveBeenCalled();
    });

    it("preserves detail view state when preserveDetailViewState is true", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      const mockDetailView = { reset: jest.fn() };
      pdfPageView.detailView = mockDetailView;

      pdfPageView.reset({ preserveDetailViewState: true });

      // detailView.reset should be called with keepCanvas: false (default)
      expect(mockDetailView.reset).toHaveBeenCalledWith({ keepCanvas: false });
      // detailView should not be nulled
      expect(pdfPageView.detailView).toBe(mockDetailView);
    });

    it("preserves detail view and canvas wrapper when both flags are true", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      const mockDetailView = { reset: jest.fn() };
      pdfPageView.detailView = mockDetailView;

      pdfPageView.reset({ preserveDetailViewState: true, keepCanvasWrapper: true });

      expect(mockDetailView.reset).toHaveBeenCalledWith({ keepCanvas: true });
      expect(pdfPageView.detailView).toBe(mockDetailView);
    });

    it("keeps pdfBugGroupsLayer if pdfPage._pdfBug is true", () => {
      const pdfPageWithBug = { ...pdfPageMock, _pdfBug: true };
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageWithBug;

      const bugDiv = document.createElement("div");
      bugDiv.classList.add("pdfBugGroupsLayer");
      pdfPageView.div.append(bugDiv);

      const extraDiv = document.createElement("div");
      pdfPageView.div.append(extraDiv);

      pdfPageView.reset();

      expect(pdfPageView.div.contains(bugDiv)).toBe(true);
      expect(pdfPageView.div.contains(extraDiv)).toBe(false);
    });

    it("updates internal layers array when nodes are removed", () => {
      const pdfPageView = new PDFPageView({
        container,
        defaultViewport: pdfPageMock.viewport,
      });
      pdfPageView.pdfPage = pdfPageMock;

      const node1 = document.createElement("div");
      const node2 = document.createElement("div");
      pdfPageView.div.append(node1, node2);

      // Here, we verify the side effect on DOM which implies the logic ran.
      pdfPageView.reset();

      expect(pdfPageView.div.contains(node1)).toBe(false);
      expect(pdfPageView.div.contains(node2)).toBe(false);
    });
  });
});

