      transfers
    );
  });

  it("should store the controller and startCapability on streamControllers", async () => {
    const reader = messageHandler
      .sendWithStream("actionName", {}, {}, [])
      .getReader();

    const controllerInfo = messageHandler.streamControllers[1];
    expect(controllerInfo).toBeDefined();
    expect(controllerInfo.controller).toBeDefined();
    expect(controllerInfo.startCall).toBeDefined();
    expect(controllerInfo.pullCall).toBeNull();
    expect(controllerInfo.cancelCall).toBeNull();
    expect(controllerInfo.isClosed).toBe(false);
  });

  it("should post a pull message when the stream is pulled and wait for resolution", async () => {
    const stream = messageHandler.sendWithStream("actionName", {}, {}, []);
    const reader = stream.getReader();

    // Reset mock to clear the 'start' call
    mockComObj.postMessage.mockClear();

    const pullPromise = reader.read();

    expect(mockComObj.postMessage).toHaveBeenCalledWith({
      sourceName: "source",
      targetName: "target",
      stream: StreamKind.PULL,
      streamId: 1,
      desiredSize: 1,
    });

    // Simulate the response resolving the pull
    messageHandler.streamControllers[1].pullCall.resolve();

    await expect(pullPromise).resolves.toEqual({ value: undefined, done: false });
  });

  it("should post a cancel message when the stream is cancelled", async () => {
    const stream = messageHandler.sendWithStream("actionName", {}, {}, []);
    const reader = stream.getReader();
    const error = new Error("Cancelled");

    // Reset mock to clear the 'start' call
    mockComObj.postMessage.mockClear();

    const cancelPromise = reader.cancel(error);

    const controllerInfo = messageHandler.streamControllers[1];
    expect(controllerInfo.isClosed).toBe(true);
    expect(controllerInfo.cancelCall).toBeDefined();

    expect(mockComObj.postMessage).toHaveBeenCalledWith({
      sourceName: "source",
      targetName: "target",
      stream: StreamKind.CANCEL,
      streamId: 1,
      reason: error,
    });

    // Resolve the cancel capability to complete the async flow
    controllerInfo.cancelCall.resolve();

    await expect(cancelPromise).resolves.toBeUndefined();
  });

  it("should assert if cancel reason is not an Error", async () => {
    const stream = messageHandler.sendWithStream("actionName", {}, {}, []);
    const reader = stream.getReader();

    // We expect reader.cancel to throw synchronously
    expect(() => reader.cancel("not an error")).toThrow(
      "cancel must have a valid reason"
    );
  });

  it("should wait for start capability to resolve before finishing start", async () => {
    let resolveStart;
    const originalWithResolvers = Promise.withResolvers;
    Promise.withResolvers = () => {
      const caps = originalWithResolvers();
      // Hijack the first one which should be startCall
      if (!resolveStart) {
        resolveStart = caps.resolve;
      }
      return caps;
    };

    const stream = messageHandler.sendWithStream("actionName", {}, {}, []);
    const reader = stream.getReader();

    // Read attempts to acquire a lock, implicitly waiting for start to finish in some implementations,
    // but explicitly we just want to ensure the internal promise logic works.
    // We verify by checking that our intercepted resolve exists.
    expect(resolveStart).toBeDefined();

    // Clean up
    resolveStart();
    Promise.withResolvers = originalWithResolvers;

    // Ensure no hanging promises
    await reader.cancel();
  });
});

